/**
 * The CPU (wasm) drum output for demucs.ts testMix(), every 64th sample:
 * what a GPU runtime must reproduce before separation runs on it.
 * Generated by local/make-signature.ts from the model with SHA-256
 * 5943fde7eff1… (stemmodel.ts); regenerate if the model or demucs.ts changes.
 */
const B64 =
  '';

export function cpuSignature(): Float32Array {
  const bin = atob(B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Float32Array(bytes.buffer);
}
